// NAVBAR
function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const [menuAberto, setMenuAberto] = useState(false)

  useEffect(() => {
    const checarScroll = () => setScrolled(window.scrollY > 50)
    window.addEventListener('scroll', checarScroll)
    return () => window.removeEventListener('scroll', checarScroll)
  }, [])

  const itens = [
    ['#sobre','Sobre'], ['#sensor','Sensor'], ['#gantt','Gantt'],
    ['#w5h2','5W2H'], ['#producao','Produção'], ['#dashboard','Dashboard'],
    ['#site','Site'], ['#jogo','Jogo'], ['#equipe','Equipe'],
  ]

  return (
    <nav className={`nav ${scrolled ? 'nav-solid' : ''} ${menuAberto ? 'nav-open' : ''}`}>
      <div className="nav-centro">
        <a href="#topo" className="nav-logo">AuraBrew</a>

        <ul className={`nav-itens ${menuAberto ? 'aberto' : ''}`}>
          {itens.map(([href, label]) => (
            <li key={href}>
              <a href={href} onClick={() => setMenuAberto(false)}>{label}</a>
            </li>
          ))}
        </ul>

        <button
          className="nav-burger"
          onClick={() => setMenuAberto(!menuAberto)}
          aria-label="menu"
        >
          <span className={menuAberto ? 'ativo' : ''}/>
          <span className={menuAberto ? 'ativo' : ''}/>
          <span className={menuAberto ? 'ativo' : ''}/>
        </button>
      </div>
    </nav>
  )
}

