// GANTT 
function Gantt() {
  const [ref, vis] = useVisivel()
  return (
    <section className={`secao ${vis ? 'aparece' : ''}`} id="gantt" ref={ref}>
      <div className="caixa">
        <div className="topo-secao">
          <span className="rotulo">Gestão · Cronograma</span>
          <h2>Gráfico de <em>Gantt</em></h2>
          <p className="subtitulo">Projeto Cervejeiro (Aura Brew)</p>
          <div className="linha-dec"/>
        </div>

        <div className="tabela-scroll">
          <table className="tabela-gantt">
            <thead>
              <tr>
                <th className="col-ativ">Atividade</th>
                <th className="col-resp">Responsável</th>
                {semanas.map(s => <th key={s} className="col-sem">{s}</th>)}
              </tr>
            </thead>
            <tbody>
              {listaAtividades.map((t,ri) => {
                const set = new Set(t.sem)
                const mn = Math.min(...t.sem), mx = Math.max(...t.sem)
                return (
                  <tr key={ri} className={ri%2===0 ? 'tr-zebra' : ''}>
                    <td className="td-nome">{t.nome}</td>
                    <td className="td-resp">{t.resp}</td>
                    {Array.from({length:14},(_,w) => {
                      const on = set.has(w)
                      let br = ''
                      if(on && w===mn && w===mx) br = '5px'
                      else if(on && w===mn) br = '5px 0 0 5px'
                      else if(on && w===mx) br = '0 5px 5px 0'
                      return (
                        <td key={w} className="td-bar">
                          <div style={{
                            height: 18,
                            background: on ? '#e8451a' : 'transparent',
                            borderRadius: br || 0,
                            opacity: .85,
                          }}/>
                        </td>
                      )
                    })}
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
        <p className="gantt-nota">▓ Planejado · Sem11→Sem24 · Março a Junho 2026</p>
      </div>
    </section>
  )
}

